INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('pure_water', 'Pure Water', 'Consumables', 'Grants Res+10. (Decreases by 2 every 1 turn.)', 'Get Pure Water from Dagsion''s Item Shop; You can get Pure Water from the Item Shop in Dagsion for 500 Gold each.; Fast travel to the Shopping Arcade in Dagsion to find the Item Shop and select Buy from the shopkeeper to see his list of wares.; Found in a Treasure Chest in Nowah''s Cave Elektra; You can find Pure Water in a Treasure Chest inside Nowah''s Cave Elektra. Explore the dungeon to locate the chest''s whereabouts. The indicator on the top right of the screen shows if you''ve found all of the chests in the dungeon.');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('dew_of_protection', 'Dew of Protection', 'Consumables', 'Unit takes half damage until unit''s next phase.', NULL);
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('heavy_armor_manual', 'Heavy-Armor Manual', 'Consumables', 'Use to slightly increase heavy-armor skill.', NULL);
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('riding_manual', 'Riding Manual', 'Consumables', 'Use to slightly increase riding skill.', NULL);
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('flying_manual', 'Flying Manual', 'Consumables', 'Use to slightly increase flying skill.', NULL);
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('elixir', 'Elixir', 'Consumables', 'Restores 100 HP.', NULL);
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('linking_rock', 'Linking Rock', 'Consumables', 'Restores 40 LP. Only usable in clashes.', NULL);
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('yarc_milk', 'Yarc Milk', 'Gifts', 'Milk from yarc. It is known for its nutritional benefits. Primarily enjoyed by children.', 'Bought from a Shop; Yarc Milk is an Item that can be bought for 50 Gold. You can find them in the locations above. Usually, you can only buy these gifts once before they need to be restocked. Make sure to use them wisely!');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('ginji_cervi', 'Ginji Cervi', 'Gifts', NULL, 'Bought from a Shop; Ginji Cervi is an Item that can be bought for 150 Gold. You can find them in the locations above. Usually, you can only buy these gifts once before they need to be restocked. Make sure to use them wisely!');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('rustic_ghosh', 'Rustic Ghosh', 'Gifts', NULL, 'Bought from a Shop; Rustic Ghosh is an Item that can be bought for 100 Gold. You can find them in the locations above. Usually, you can only buy these gifts once before they need to be restocked. Make sure to use them wisely!');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('strategy_manuscript', 'Strategy Manuscript', 'Gifts', NULL, 'Bought from a Shop; Strategy Manuscript is an Item that can be bought for 500 Gold. You can find them in the locations above. Usually, you can only buy these gifts once before they need to be restocked. Make sure to use them wisely!');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('wing_fletching', 'Wing Fletching', 'Gifts', NULL, 'Bought from a Shop; Wing Fletching is an Item that can be bought for 300 Gold. You can find them in the locations above. Usually, you can only buy these gifts once before they need to be restocked. Make sure to use them wisely!');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('strong_cervi', 'Strong Cervi', 'Gifts', 'Fresh, rich cervi. Its sweetness and acidity make it difficult to drink. Primarily enjoyed by children.', 'Bought from a Shop; Strong Cervi is an Item that can be bought for 100 Gold. You can find them in the locations above. Usually, you can only buy these gifts once before they need to be restocked. Make sure to use them wisely!');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('southern_ghosh', 'Southern Ghosh', 'Gifts', 'Imported ghosh from Mosa with a very bold, rich flavor. Primarily enjoyed by lovers of fermented drinks.', 'Bought from a Shop; Southern Ghosh is an Item that can be bought for 135 Gold. You can find them in the locations above. Usually, you can only buy these gifts once before they need to be restocked. Make sure to use them wisely!; Reward From Gifts of the Marketplace!; Southern Ghosh can be acquired after completing the quest Gifts of the Marketplace!. Follow the quest''s instructions and report back to receive the gift as a reward.');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('home_recipe_book', 'Home-Recipe Book', 'Gifts', 'A collection of home-cooked meals from around the world. Primarily enjoyed by those who love to cook.', 'Bought from a Shop; Home-Recipe Book is an Item that can be bought for 300 Gold. You can find them in the locations above. Usually, you can only buy these gifts once before they need to be restocked. Make sure to use them wisely!');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('rare_spices', 'Rare Spices', 'Gifts', 'Extremely rare spices packed in a luxurious presentation box. Primarily enjoyed by spicy-food lovers.', 'Bought from a Shop; Rare Spices is an Item that can be bought for 500 Gold. You can find them in the locations above. Usually, you can only buy these gifts once before they need to be restocked. Make sure to use them wisely!');
