INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('eastern_earrings', 'Eastern Earrings', 'Gifts', 'Beautiful gold earrings from the east with deep-green beads. Primarily enjoyed by fashion lovers.', 'Bought from a Shop; Eastern Earrings is an Item that can be bought for 720 Gold. You can find them in the locations above. Usually, you can only buy these gifts once before they need to be restocked. Make sure to use them wisely!');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('pickled_bulbs', 'Pickled Bulbs', 'Gifts', 'A sour, preserved food made by pickling vegetable bulbs in vinegar. Primarily enjoyed by vegetable lovers.', 'Bought from a Shop; Pickled Bulbs is an Item that can be bought for 90 Gold. You can find them in the locations above. Usually, you can only buy these gifts once before they need to be restocked. Make sure to use them wisely!; Reward From A Taste from Home; Pickled Bulbs can be acquired after completing the quest A Taste from Home. Follow the quest''s instructions and report back to receive the gift as a reward.; A Taste from Home Quest Walkthrough');
