INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('adamantine', 'Adamantine', 'Ores', NULL, 'Currently Unknown; We''re currently investigating the sources of Adamantine. We will update this page as soon as possible, but you can also help via the comments section!');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('warrior_s_soulstone', 'Warrior''s Soulstone', 'Ores', NULL, 'Found in Dungeons; You can acquire Warrior''s Soulstone by destroying crystals in dungeons. The ore you get upon destroying a crystal is random, and you can enter and exit the dungeon until you get the necessary amount of ore.');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('nemearite', 'Nemearite', 'Ores', NULL, 'Found in Dungeons; You can acquire Nemearite by destroying crystals in dungeons. The ore you get upon destroying a crystal is random, and you can enter and exit the dungeon until you get the necessary amount of ore.');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('agarthium', 'Agarthium', 'Ores', NULL, 'Found in Dungeons; You can acquire Agarthium by destroying crystals in dungeons. The ore you get upon destroying a crystal is random, and you can enter and exit the dungeon until you get the necessary amount of ore.');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('black_sand_steel', 'Black-Sand Steel', 'Ores', 'A high-quality ore, often found in iron mines. Known for its low rate of carbon and other impurities.', 'Found in Dungeons; You can acquire Black-Sand Steel by destroying crystals in dungeons. The ore you get upon destroying a crystal is random, and you can enter and exit the dungeon until you get the necessary amount of ore.; Search in an Area on the World Map; You can acquire Black-Sand Steel by gathering them in Search areas on the World Map. The Item you get upon searching is random, so keep searching the area until you get the necessary amount of Black-Sand Steel.; You can also hover an area in the World Map to see which Item you can get from searching it.');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('blue_snoll', 'Blue Snoll', 'Ores', 'A rare ore that occasionally forms in dark, cold places. It glows with a plae-blue light.', 'Found in Dungeons; You can acquire Blue Snoll by destroying crystals in dungeons. The ore you get upon destroying a crystal is random, and you can enter and exit the dungeon until you get the necessary amount of ore.');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('cullet', 'Cullet', 'Ores', 'A sturdy crystal shard, found in caves throughout the land. Often used in smithing to sharpen blades.', 'Found in Dungeons; You can acquire Cullet by destroying crystals in dungeons. The ore you get upon destroying a crystal is random, and you can enter and exit the dungeon until you get the necessary amount of ore.; Obtained as a Quest Reward; You can obtain Cullet, 3000 Gold, and 80 Renown Points as a reward for completing the One Last Challenge quest. See the table above for details and complete it to receive Cullet.; One Last Challenge Quest Walkthrough');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('lunar_stone', 'Lunar Stone', 'Ores', NULL, 'Found in Dungeons; You can acquire Lunar Stone by destroying crystals in dungeons. The ore you get upon destroying a crystal is random, and you can enter and exit the dungeon until you get the necessary amount of ore.');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('orichalcum', 'Orichalcum', 'Ores', 'A rare mineral with a gold sparkle. It can store magic within itself and is strictly regulated by the temples.', 'Currently Unknown; We''re currently investigating the sources of Orichalcum. We will update this page as soon as possible, but you can also help via the comments section!');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('phlogiston', 'Phlogiston', 'Ores', 'A very durable mineral, only found in specific places. It creates sparks when struck with the right metal.', 'Found in Dungeons; You can acquire Phlogiston by destroying crystals in dungeons. The ore you get upon destroying a crystal is random, and you can enter and exit the dungeon until you get the necessary amount of ore.');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('sea_star_stone', 'Sea-Star Stone', 'Ores', 'A rare ore that forms in caves near the ocean. It contains the power of the sea.', 'Currently Unknown; We''re currently investigating the sources of Sea-Star Stone. We will update this page as soon as possible, but you can also help via the comments section!');
INSERT INTO items (id, name, category, effect, how_to_get) VALUES ('smithing_stone', 'Smithing Stone', 'Ores', 'A common ore found throughout the land. Known as a cornerstone in smithing materials.', 'Found in Dungeons; You can acquire Smithing Stone by destroying crystals in dungeons. The ore you get upon destroying a crystal is random, and you can enter and exit the dungeon until you get the necessary amount of ore.; Search in an Area on the World Map; You can acquire Smithing Stone by gathering them in Search areas on the World Map. The Item you get upon searching is random, so keep searching the area until you get the necessary amount of Smithing Stone.; You can also hover an area in the World Map to see which Item you can get from searching it.');
