INSERT INTO character_class_recommendations (character_id, overall_tier, strengths_summary, beginner_class_id, specialty_class_id, advanced_class_id, master_class_id, divine_class_id) VALUES ('eshmel', 'Lord Tier', '["Good growths in Strength (45%), Dexterity (45%), and Speed (45%), which makes them a strong and accurate unit that doubles foes often."]', NULL, NULL, NULL, NULL, NULL);
INSERT INTO character_class_recommendations (character_id, overall_tier, strengths_summary, beginner_class_id, specialty_class_id, advanced_class_id, master_class_id, divine_class_id) VALUES ('hong_hua', 'B Tier', '["Has good growths in Magic (45%), Skill (45%), and Speed (45%), making her a strong and accurate magic unit that doubles often.","Can be easily trained as an Ovate due to her Black Magic proficiency.","Her Personal Ability increases her Hit when Magic is equipped."]', NULL, NULL, 'ovate', 'druid', NULL);
INSERT INTO character_class_recommendations (character_id, overall_tier, strengths_summary, beginner_class_id, specialty_class_id, advanced_class_id, master_class_id, divine_class_id) VALUES ('troy', 'B Tier', '["Good growths in Strength (45%), Magic (45%), and Dexterity (50%), which allows her to become a versatile attacker.","Can be easily trained as a War Monk due to her Black Magic, White Magic, and Brawling proficiencies.","Can increase Hit when using Gauntlets thanks to her Personal Ability,"]', NULL, NULL, NULL, 'war_monk', 'the_godhand');
INSERT INTO character_class_recommendations (character_id, overall_tier, strengths_summary, beginner_class_id, specialty_class_id, advanced_class_id, master_class_id, divine_class_id) VALUES ('cai', 'Lord Tier', '["Great growths in Strength (45%), Dexterity (45%), and Speed (45%), resulting in a good balance of firepower, accuracy, and follow-up attacks.","Profciencies in Mounts and Spears is great for Orichaldia and The Cavalier.","Personal skill Brio, grants Movement +1, which synergizes well with his proficiency in Mounts.","Can also be built with a focus on Mag with skills like Nosferatu, Thoron, and Bolganone"]', 'ornius_rider', 'light_cavalry', 'bardinger', 'orichaldia', 'the_cavalier');
INSERT INTO character_class_recommendations (character_id, overall_tier, strengths_summary, beginner_class_id, specialty_class_id, advanced_class_id, master_class_id, divine_class_id) VALUES ('dietrich', 'Lord Tier', '["Great growths in Speed (50%), Dexterity (60%), and Luck (50%) making him a reliable dodge tank with accurate attacks.","Easy to develop as a Shido due to his proficiencies in Swords and Infantry.","His Personal Ability, Murderous Intent, grants him +5 Crit when he attacks first."]', 'gladiator', 'myrmidon', 'shido', 'swordmaster', 'the_blade');
INSERT INTO character_class_recommendations (character_id, overall_tier, strengths_summary, beginner_class_id, specialty_class_id, advanced_class_id, master_class_id, divine_class_id) VALUES ('theodora', 'Lord Tier', '["Great growths in HP (70% and Defense (40%), making it easy for her to act as a tank in the front lines.","Easy to develop as a Bardinger due to her proficiencies in Spears and Authority.","Her Personal Ability, Royal Resolve, has a 30% chance of halving the damage that she takes."]', 'gladiator', 'armored_ornius_rider', 'guardian', 'sentinel', 'the_trident');
INSERT INTO character_class_recommendations (character_id, overall_tier, strengths_summary, beginner_class_id, specialty_class_id, advanced_class_id, master_class_id, divine_class_id) VALUES ('leda', 'Lord Tier', '["Great growth in Speed (65%), which makes it easy for her to avoid and double attack foes.","Can be easily trained as a Sniper due to her Bow proficiency.","Her personal skill can nullify counterattacks."]', 'hunter', 'archer', 'dancer', 'shadow_seeker', 'the_apsara');
