INSERT INTO character_class_recommendations (character_id, overall_tier, strengths_summary, beginner_class_id, specialty_class_id, advanced_class_id, master_class_id, divine_class_id) VALUES ('tahonia', 'D Tier', '["Amazing growths in Str (50%) and Skl (40%), offensive capabilities can be easily supplemented with personal skills and class bonuses.","Best used as a Battle Master by utilizing his proficiency in Gauntlets, the class gives him more bonuses to Str (+25) and Skl (+5).","Personal skillhas a 15% chance when using gauntlet Combat Arts. Allows for a follow-up attack regardless of attack speed."]', NULL, NULL, NULL, NULL, NULL);
INSERT INTO character_class_recommendations (character_id, overall_tier, strengths_summary, beginner_class_id, specialty_class_id, advanced_class_id, master_class_id, divine_class_id) VALUES ('klapka', 'D Tier', '["With a decent Growth rate in Defense (50%) and Skill (45%), he can easily withstand physical attacks and counterattack.","His personal ability gives him up to +10 defense until the end of the map, making him tougher the more he fights.","He excels at lances and white magic."]', NULL, NULL, NULL, NULL, NULL);
